from taf.ue.tm500.asc.command import base
from taf.ue.tm500.asc.exception import ASCResponseError, NoResourceNameFound


class ShowGroups(base.Command):
    def _generate(self, **kwargs):
        return r'showgroups'

    def _parse_output(self, content):
        #  based on sw 1.13.0
        lines = self._split_lines(content)
        groups = []
        for line in lines:
            attributes = self._split_columns(line)
            if len(attributes) <= 1:
                continue
            groups.append(tuple(attributes))
        return groups


class UserName(base.Command):
    def _generate(self, name=None, **kwargs):
        return rf'username {name}'


