class SetPowerOn(base.Command):
    def _generate(self, group_name=None, **kwargs):
        return rf'setpower on {group_name}'


class SetPowerOff(base.Command):
    def _generate(self, group_name=None, **kwargs):
        return rf'setpower off {group_name}'


class ShowPower(base.Command):
    def _generate(self, group_name=None, **kwargs):
        return rf'showpower {group_name}'

    def _parse_output(self, content):
        lines = self._split_lines(content)
        for line in lines:
            if line.endswith('On') or line.endswith('Off'):
                continue
            lines.remove(line)

        if len(lines) != 1:
            raise ASCResponseError(f"response error: {content}")
        error_reason_key_string = 'Status: 2: Not found'
        power_line = lines[0]
        if error_reason_key_string in power_line:
            raise NoResourceNameFound(f"failed to show power, error:{power_line}")

        attributes = self._split_columns(power_line)
        return attributes[1]


class GetVersion(base.Command):
    def _generate(self, **kwargs):
        return r'getversion'

    def _parse_output(self, content):
        lines = self._split_lines(content)
        attr_dic = {}
        for line in lines:
            if ":" not in line:
                continue
            key, value = line.split(":", 1)

            attr_dic[key.strip()] = value.strip()
        return attr_dic


class RandomCommand(base.Command):
    def _generate(self, command=None, **kwargs):
        return command
